"""Module 10 of the heavy call graph."""


def fn_10_0(a, b):
    t1 = a * 1 - b
    t2 = a * 2 - b
    t3 = a * 3 - b
    t4 = a * 4 - b
    t5 = a * 5 - b
    t6 = a * 6 - b
    t7 = a * 7 - b
    t8 = a * 8 - b
    t9 = a * 9 - b
    t10 = a * 10 - b
    return shared(t10, b) + fn_11_0(a, b)


